<script setup lang="ts">
const insightsUrl=import.meta.env.DEV?'http://127.0.0.1:18869':'/insights.html'
import PageHeader from '../workspace/PageHeader.vue'
import {onMounted,ref} from 'vue'
import {api} from '../api'
import {useRequestScope} from '../platform/request-scope'
import PublicationReview from '../authoring/PublicationReview.vue'
import BetaOperations from '../experience/BetaOperations.vue'
import ProductNav from './ProductNav.vue'
import DefaultModelsSettings from './DefaultModelsSettings.vue'
import {operationKey,completeOperation} from './operation-key'
type Dict=Record<string,any>
const tab=ref('overview'),error=ref(''),notice=ref(''),busy=ref(false),ready=ref(false),overview=ref<Dict>(),users=ref<Dict[]>([]),total=ref(0),userQuery=ref(''),invites=ref<Dict[]>([]),tasks=ref<Dict[]>([]),audits=ref<Dict[]>([]),holds=ref<Dict[]>([]),policy=ref<Dict>(),capture=useRequestScope()
const products=ref<Dict[]>([]),orders=ref<Dict[]>([]),orderTotal=ref(0),orderQuery=ref(''),orderState=ref(''),orderOffset=ref(0),userOffset=ref(0),catalogTotal=ref(0),catalogOffset=ref(0)
let loadVersion=0,orderVersion=0,userVersion=0,catalogVersion=0
const chosen=ref<Dict>(),credits=ref(0),memberDays=ref(0),dailyCredits=ref(0),reason=ref('内测体验'),editStatus=ref('active'),editRole=ref('USER'),memo=ref('')
const inviteForm=ref({label:'首轮内测',maxUses:10,validDays:30,reward:0,admission:true}),cardForm=ref({credits:1000,memberDays:0,validDays:30}),resultCode=ref('')
const catalogForm=ref({sku:'',title:'',kind:'credits',amountMinor:0,currency:'CNY',credits:0,memberDays:0,dailyCredits:0,active:false}),inviteRequired=ref(false),billingEnabled=ref(false),signinCredits=ref(0),prices=ref('{}')
function operationName(name:string){return ['grant','user'].includes(name)?name+':'+chosen.value?.id:name}
function key(name:string){return operationKey(operationName(name))}
const dates=(value:string)=>new Date(value).toLocaleString('zh-CN')
async function load(){const scope=capture(),attempt=++loadVersion;error.value='';try{const [o,u,i,p,j,a,h]=await Promise.all([api<Dict>('/product/admin/overview'),api<Dict>('/product/admin/users?query='+encodeURIComponent(userQuery.value)),api<Dict>('/product/admin/invites'),api<Dict>('/product/admin/policy'),api<Dict>('/product/admin/tasks'),api<Dict>('/product/admin/audit'),api<Dict>('/product/admin/holds')]);if(!scope.valid()||attempt!==loadVersion)return;overview.value=o;users.value=u.items;total.value=u.total;invites.value=i.items;policy.value=p;tasks.value=j.items;audits.value=a.items;inviteRequired.value=p.beta.inviteRequired;billingEnabled.value=p.billing.enabled;signinCredits.value=p.growth.signinCredits;prices.value=JSON.stringify(p.billing.prices,null,2);ready.value=true;await Promise.all([loadUsers(userOffset.value),loadOrders(orderOffset.value),loadCatalog(catalogOffset.value)])}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function mutate(name:string,path:string,body:Dict,method='POST'){const scope=capture(),operation=operationName(name);busy.value=true;error.value='';notice.value='';try{const result=await api<Dict>(path,{method,body:{...body,requestKey:key(name)}});if(!scope.valid())return;completeOperation(operation);notice.value='操作已保存，并已记录审计流水';if(result.code)resultCode.value=result.code;await load()}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function loadUsers(offset=0){const scope=capture(),attempt=++userVersion;try{const result=await api<Dict>('/product/admin/users?query='+encodeURIComponent(userQuery.value)+'&offset='+offset);if(scope.valid()&&attempt===userVersion){users.value=result.items;total.value=result.total;userOffset.value=offset}}catch(e){if(scope.valid()&&attempt===userVersion)error.value=(e as Error).message}}
async function loadOrders(offset=0){const scope=capture(),attempt=++orderVersion;try{const result=await api<Dict>('/product/admin/orders?query='+encodeURIComponent(orderQuery.value)+'&state='+encodeURIComponent(orderState.value)+'&offset='+offset);if(scope.valid()&&attempt===orderVersion){orders.value=result.items;orderTotal.value=result.total;orderOffset.value=offset}}catch(e){if(scope.valid()&&attempt===orderVersion)error.value=(e as Error).message}}
async function loadCatalog(offset=0){const scope=capture(),attempt=++catalogVersion;try{const result=await api<Dict>('/product/admin/catalog?offset='+offset);if(scope.valid()&&attempt===catalogVersion){products.value=result.items;catalogTotal.value=result.total;catalogOffset.value=offset}}catch(e){if(scope.valid()&&attempt===catalogVersion)error.value=(e as Error).message}}
function editProduct(product:Dict){catalogForm.value={sku:product.sku,title:product.title,kind:product.kind,amountMinor:product.amountMinor,currency:product.currency,credits:product.credits,memberDays:product.memberDays,dailyCredits:product.dailyCredits,active:product.active}}
const orderLabel=(state:string)=>({created:'等待结账',checkout_started:'创建收银台中',pending:'等待支付',checkout_ready:'等待支付',unknown:'需核查',paid:'已核验支付',review:'退款或改价待处理'} as Record<string,string>)[state]||state
function selectUser(user:Dict){chosen.value=user;editStatus.value=user.status;editRole.value=user.role;memo.value=user.memo;credits.value=0;memberDays.value=0;dailyCredits.value=0}
function grant(){if(!chosen.value||!confirm(`向 ${chosen.value.username} 发放 ${credits.value} 积分、${memberDays.value} 天会员？`))return;void mutate('grant','/product/admin/users/'+chosen.value.id+'/grant',{credits:credits.value,memberDays:memberDays.value,dailyCredits:dailyCredits.value,reason:reason.value})}
function saveUser(){if(!chosen.value||!confirm(`更新 ${chosen.value.username} 的账号状态和角色？`))return;void mutate('user','/product/admin/users/'+chosen.value.id,{status:editStatus.value,role:editRole.value,memo:memo.value},'PUT')}
function savePolicy(){let value:unknown;try{value=JSON.parse(prices.value)}catch{error.value='积分定价必须是有效的 JSON 对象';return}if(!confirm(`保存内测规则？邀请门槛：${inviteRequired.value?'开启':'关闭'}；积分计费：${billingEnabled.value?'开启':'关闭'}。`))return;void mutate('policy','/product/admin/policy',{inviteRequired:inviteRequired.value,billingEnabled:billingEnabled.value,signinCredits:signinCredits.value,prices:value},'PUT')}
async function disableInvite(invite:Dict){if(!confirm(`停用“${invite.label}”的邀请码？`))return;const scope=capture();try{await api('/product/admin/invites/'+invite.id,{method:'DELETE'});if(scope.valid())await load()}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function reviewHold(id:string){const scope=capture();busy.value=true;error.value='';try{const result=await api<Dict>('/product/admin/holds/'+id+'/reconcile',{method:'POST'});if(scope.valid()){notice.value=result.message;await load()}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
const factLabel=(name:string)=>({'fact.account.registered':'注册完成','fact.account.login':'登录','fact.sample.entered':'进入预制案例','fact.first_action.success':'首次行动成功','fact.investigation.completed':'调查完成','fact.aftermath.resolved':'善后完成','fact.second_ending.started':'开始第二条结局','fact.order.paid':'核验支付成功'} as Record<string,string>)[name]||name
onMounted(load)
</script>
<template><div class="product-page"><PageHeader title="运营管理" description="管理内测账号、作品审核、任务与权益。"><a :href="insightsUrl" target="_blank" rel="noopener" class="inline-link">打开独立数据站 ↗</a><button :disabled="busy" @click="load">刷新数据</button></PageHeader><ProductNav admin/><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="product-hint" role="status">{{notice}}</p><template v-if="ready"><nav class="product-tabs" aria-label="运营功能"><button v-for="item in [{id:'overview',label:'体验数据'},{id:'users',label:'账号与发放'},{id:'growth',label:'内测邀请'},{id:'publications',label:'作品审核'},{id:'models',label:'默认模型'},{id:'catalog',label:'商品与规则'},{id:'orders',label:'订单核查'},{id:'tasks',label:'任务诊断'},{id:'audit',label:'操作审计'}]" :key="item.id" :aria-selected="tab===item.id" @click="tab=item.id">{{item.label}}</button></nav><DefaultModelsSettings v-if="tab==='models'"/><section v-if="tab==='overview'&&overview"><BetaOperations/><div class="product-metrics"><div class="product-metric">账号总数<strong>{{overview.users}}</strong></div><div class="product-metric">近 7 日活跃<strong>{{overview.active7d}}</strong></div><div class="product-metric">未知积分预留<strong>{{overview.unknownHolds}}</strong></div><div class="product-metric">调查完成<strong>{{overview.facts['fact.investigation.completed']||0}}</strong></div><div class="product-metric">善后完成<strong>{{overview.facts['fact.aftermath.resolved']||0}}</strong></div><div class="product-metric">待核查订单<strong>{{overview.quality.reviewOrders}}</strong></div></div><div class="product-grid"><section class="product-card"><h2>体验漏斗</h2><p class="product-note">正式存档记录完成状态；页面点击只用于观察使用行为。</p><div v-for="name in ['fact.account.registered','fact.sample.entered','fact.first_action.success','fact.investigation.completed','fact.aftermath.resolved','fact.second_ending.started']" :key="name" class="list-item row between"><span>{{factLabel(name)}}</span><strong>{{overview.facts[name]||0}}</strong></div><p class="product-note">采集开始：{{overview.collectionStartedAt?dates(overview.collectionStartedAt):'尚无事件'}}。历史体验不自动补记为新数据。</p></section><section class="product-card"><h2>收入与成本</h2><p>{{overview.revenueBasis}}</p><p v-for="item in overview.revenue" :key="item.currency+item.environment">{{item.environment==='test'?'测试':'生产'}} · {{item.currency}} {{(item.amount/100).toFixed(2)}} · {{item.payments}} 次支付</p><p v-if="!overview.revenue.length" class="product-empty">暂无经过核验的收款</p><p v-for="cost in overview.providerCost" :key="cost.currency">已知供应商成本：{{cost.currency}} {{cost.amount}} · {{cost.calls}} 次调用</p><p class="product-note">{{overview.providerCostReason}}</p></section><section class="product-card product-span"><h2>活跃趋势</h2><div v-if="overview.trends.length" class="product-chart" role="img" aria-label="近 30 日活跃人数，具体数值见下表"><div v-for="item in overview.trends" :key="item.day" :title="item.day+': '+item.users+' 人'" :style="{height:(Math.max(2,item.users/Math.max(1,...overview.trends.map((d:Dict)=>d.users))*100))+'%'}"></div></div><div class="product-scroll"><table class="product-table"><thead><tr><th>日期</th><th>活跃账号</th><th>事件</th></tr></thead><tbody><tr v-for="item in overview.trends" :key="item.day"><td>{{item.day}}</td><td>{{item.users}}</td><td>{{item.events}}</td></tr></tbody></table></div></section><section class="product-card product-span"><h2>次日留存</h2><p class="product-note">以首次采集日作为 cohort；完整次日结束后才计算 D1。尚未成熟显示“等待次日结束”。</p><div class="product-scroll"><table class="product-table"><thead><tr><th>首次体验日</th><th>账号</th><th>次日返回</th><th>D1</th></tr></thead><tbody><tr v-for="item in overview.retention" :key="item.day"><td>{{item.day}}</td><td>{{item.cohort}}</td><td>{{item.returned??'等待次日结束'}}</td><td>{{item.d1===null?'—':(item.d1*100).toFixed(1)+'%'}}</td></tr></tbody></table></div></section><section class="product-card"><h2>页面使用</h2><p v-for="item in overview.pages" :key="item.path">{{item.path}} · {{item.views}} 次</p><p v-if="!overview.pages.length" class="product-empty">暂无页面数据</p></section><section class="product-card"><h2>任务与调用</h2><p v-for="(count,state) in overview.taskStates" :key="state">任务 {{state}} · {{count}}</p><p v-for="(count,state) in overview.usageStates" :key="state">调用 {{state}} · {{count}}</p></section></div></section><section v-else-if="tab==='users'" class="product-grid"><section class="product-card"><h2>账号（{{total}}）</h2><form @submit.prevent="loadUsers(0)"><label>搜索用户名<input v-model="userQuery" maxlength="32"></label><button>搜索</button></form><div v-for="user in users" :key="user.id" class="list-item"><strong>{{user.username}}</strong><p class="product-note">{{user.role}} · {{user.status}} · 可用 {{user.available}} · 冻结 {{user.frozen}}</p><button @click="selectUser(user)">管理这个账号</button></div><div class="product-actions"><button :disabled="userOffset===0||busy" @click="loadUsers(userOffset-50)">上一页账号</button><span>{{Math.min(userOffset+1,total)}}–{{Math.min(userOffset+users.length,total)}} / {{total}}</span><button :disabled="userOffset+50>=total||busy" @click="loadUsers(userOffset+50)">下一页账号</button></div></section><section v-if="chosen" class="product-card"><h2>{{chosen.username}}</h2><form @submit.prevent="grant"><label>发放积分<input v-model.number="credits" type="number" min="0" max="10000000"></label><label>会员天数<input v-model.number="memberDays" type="number" min="0" max="3660"></label><label>会员每日积分<input v-model.number="dailyCredits" type="number" min="0" max="100000"></label><label>发放理由<input v-model="reason" required minlength="2" maxlength="120"></label><button class="primary" :disabled="busy||!credits&&!memberDays">确认发放</button></form><form class="divider" @submit.prevent="saveUser"><label>账号状态<select v-model="editStatus"><option value="active">正常</option><option value="disabled">停用</option></select></label><label>角色<select v-model="editRole"><option value="USER">用户</option><option value="ADMIN">管理员</option></select></label><label>运营备注<textarea v-model="memo" maxlength="1000"></textarea></label><button :disabled="busy">保存账号设置</button></form></section><section v-else class="product-card product-empty">选择一个账号，可以发放内测积分、会员，或管理账号状态。</section></section><section v-else-if="tab==='growth'" class="product-grid"><section class="product-card"><h2>创建邀请码</h2><form @submit.prevent="mutate('invite','/product/admin/invites',inviteForm)"><label>批次名称<input v-model="inviteForm.label" required maxlength="100"></label><label>名额<input v-model.number="inviteForm.maxUses" type="number" min="1" max="10000" required></label><label>有效天数<input v-model.number="inviteForm.validDays" type="number" min="1" max="365" required></label><label>受邀账号积分<input v-model.number="inviteForm.reward" type="number" min="0" max="100000"></label><button class="primary" :disabled="busy">生成邀请码</button></form></section><section class="product-card"><h2>创建权益兑换卡</h2><form @submit.prevent="mutate('card','/product/admin/cards',cardForm)"><label>积分<input v-model.number="cardForm.credits" type="number" min="0" max="10000000"></label><label>会员天数<input v-model.number="cardForm.memberDays" type="number" min="0" max="3660"></label><label>有效天数<input v-model.number="cardForm.validDays" type="number" min="1" max="365"></label><button :disabled="busy||!cardForm.credits&&!cardForm.memberDays">生成兑换码</button></form></section><section v-if="resultCode" class="product-card product-span"><h2>新生成的代码</h2><p class="product-code" data-testid="generated-code">{{resultCode}}</p><p class="product-note">请保存此代码再分发给受邀用户。列表只记录批次和名额。</p></section><section class="product-card product-span"><h2>邀请批次</h2><div v-for="invite in invites" :key="invite.id" class="list-item row between"><div><strong>{{invite.label}}</strong><p>{{invite.uses}} / {{invite.maxUses}} 名额 · {{invite.reward}} 积分 · {{invite.disabled?'已停用':'可使用'}}<br><small>{{dates(invite.expiresAt)}} 到期</small></p></div><button :disabled="invite.disabled||busy" @click="disableInvite(invite)">停用</button></div></section></section><section v-else-if="tab==='catalog'" class="product-grid"><section class="product-card product-span"><h2>商品列表（{{catalogTotal}}）</h2><p v-if="!products.length" class="product-empty">暂无商品。先填写价格和权益，再决定是否上架。</p><div v-for="product in products" :key="product.id" class="list-item row between"><div><strong>{{product.title}}</strong><p>{{product.sku}} · {{product.currency}} {{(product.amountMinor/100).toFixed(2)}} · {{product.active?'已上架':'已下架'}}</p></div><button :disabled="busy" @click="editProduct(product)">编辑商品</button></div><div class="product-actions"><button :disabled="catalogOffset===0||busy" @click="loadCatalog(catalogOffset-50)">上一页商品</button><button :disabled="catalogOffset+50>=catalogTotal||busy" @click="loadCatalog(catalogOffset+50)">下一页商品</button></div></section><section class="product-card"><h2>发布商品</h2><form @submit.prevent="mutate('catalog','/product/admin/catalog',catalogForm,'PUT')"><label>商品编号<input v-model="catalogForm.sku" required pattern="[a-z0-9_-]{2,64}" maxlength="64"></label><label>名称<input v-model="catalogForm.title" required maxlength="120"></label><label>权益类型<select v-model="catalogForm.kind"><option value="credits">积分包</option><option value="member">会员</option></select></label><label>币种<select v-model="catalogForm.currency"><option>CNY</option><option>USD</option><option>EUR</option><option>HKD</option></select></label><label>售价（最小货币单位，人民币为分）<input v-model.number="catalogForm.amountMinor" required type="number" min="1" max="100000000"></label><label>积分<input v-model.number="catalogForm.credits" type="number" min="0"></label><label>会员天数<input v-model.number="catalogForm.memberDays" type="number" min="0"></label><label>会员每日积分<input v-model.number="catalogForm.dailyCredits" type="number" min="0"></label><label><input v-model="catalogForm.active" type="checkbox">上架</label><button :disabled="busy">保存商品</button></form><p class="product-note">订单保存成交时的价格和权益快照。后续调价不会改变已有订单。</p></section><section class="product-card"><h2>内测规则</h2><form @submit.prevent="savePolicy"><label><input v-model="inviteRequired" type="checkbox">注册需要邀请码</label><label><input v-model="billingEnabled" type="checkbox">启用积分计费</label><label>每日签到积分<input v-model.number="signinCredits" type="number" min="0" max="100000"></label><label>各调用阶段的固定积分定价<textarea v-model="prices" rows="8" spellcheck="false"></textarea></label><button :disabled="busy">保存规则</button></form><div class="divider"><p>收款通道：{{policy?.payment.provider}} · {{policy?.payment.enabled?'已配置':'未配置'}}</p><p>对象存储：{{policy?.storageDriver}}</p><p class="product-note">商户密钥与对象存储密钥通过服务器私密配置提供。</p></div></section></section><section v-else-if="tab==='orders'" class="product-card"><h2>订单核查（{{orderTotal}}）</h2><form @submit.prevent="loadOrders(0)"><label>用户名或完整订单编号<input v-model="orderQuery" maxlength="100"></label><label for="product-order-state">订单状态</label><select id="product-order-state" v-model="orderState"><option value="">全部状态</option><option value="paid">已核验支付</option><option value="unknown">结果未知</option><option value="review">退款或改价待处理</option><option value="created">等待结账</option></select><button :disabled="busy">查询订单</button></form><p class="product-note">这里只展示订单快照与核验结果。退款或订阅改价仍需在商户后台处理并核对权益。</p><p v-if="!orders.length" class="product-empty">没有匹配订单</p><div class="product-scroll"><table class="product-table"><thead><tr><th>账号与订单</th><th>成交商品</th><th>金额</th><th>核验状态</th><th>时间</th></tr></thead><tbody><tr v-for="order in orders" :key="order.id"><td>{{order.username}}<br><small>{{order.id}}</small></td><td>{{order.product.title}}<br><small>{{order.product.credits}} 积分 / {{order.product.memberDays}} 天会员</small></td><td>{{order.product.currency}} {{(order.product.amountMinor/100).toFixed(2)}}<br><small>{{order.provider}} · {{order.environment==='test'?'测试环境':'生产环境'}}</small></td><td>{{orderLabel(order.state)}}<br><small>{{order.verifiedPayments}} 笔已核验回执</small></td><td>{{dates(order.createdAt)}}<br><small v-if="order.paidAt">支付 {{dates(order.paidAt)}}</small></td></tr></tbody></table></div><div class="product-actions"><button :disabled="orderOffset===0||busy" @click="loadOrders(orderOffset-50)">上一页订单</button><button :disabled="orderOffset+50>=orderTotal||busy" @click="loadOrders(orderOffset+50)">下一页订单</button></div></section><section v-else-if="tab==='tasks'" class="product-card"><h2>积分预留核查</h2><p v-if="!holds.length" class="product-empty">暂无待核查的积分预留</p><div v-for="hold in holds" :key="hold.id" class="list-item"><strong>{{hold.operation}} · {{hold.reserved}} 积分 · {{hold.state==='unknown'?'结果未知':'已预留'}}</strong><p class="product-note">任务 {{hold.taskId}}</p><button :disabled="busy" @click="reviewHold(hold.id)">核查现有回执</button></div><h2 class="divider">最近任务</h2><p class="product-note">仅显示状态与数值，不显示小说、提示词或供应商密钥。未知结果保留原任务，不提供自动重发。</p><div class="product-scroll"><table class="product-table"><thead><tr><th>任务</th><th>状态</th><th>供应商</th><th>错误</th><th>调用</th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id"><td>{{task.type}}<br><small>{{task.id.slice(0,12)}}</small></td><td>{{task.state}} · {{task.persistenceState}}</td><td>{{task.providerState}}</td><td>{{task.errorCode||'—'}}</td><td><p v-for="call in task.calls" :key="call.id">{{call.operation}} · {{call.status}}<br><small>输入 {{call.inputTokens??'未知'}} / 输出 {{call.outputTokens??'未知'}}</small></p></td></tr></tbody></table></div></section><section v-else-if="tab==='audit'" class="product-card"><h2>最近操作审计</h2><div class="product-scroll"><table class="product-table"><thead><tr><th>时间</th><th>操作</th><th>对象</th><th>详情</th></tr></thead><tbody><tr v-for="item in audits" :key="item.id"><td>{{dates(item.createdAt)}}</td><td>{{item.action}}</td><td>{{item.targetId?.slice(0,12)||'—'}}</td><td><span class="product-code">{{JSON.stringify(item.details)}}</span></td></tr></tbody></table></div></section><PublicationReview v-if="ready&&tab==='publications'"/></template><p v-else-if="!error">正在确认运营权限…</p></div></template>
